 "<span style=\"font-size:14px;color:#8a8270;letter-spacing:2px\">PASAJERO</span><br><b>Tu presentación</b>": "<span style=\"font-size:14px;color:#8a8270;letter-spacing:2px\">PASSATGER</span><br><b>La teva presentació</b>",
 "<span style=\"font-size:14px;color:#8a8270;letter-spacing:2px\">DESTINO</span><br><b>PDF</b>": "<span style=\"font-size:14px;color:#8a8270;letter-spacing:2px\">DESTINACIÓ</span><br><b>PDF</b>",
